--- a/src/auth/session.ts
+++ b/src/auth/session.ts
@@ -1,6 +1,9 @@
+import {verifyToken} from '../crypto/verify'
 import { loadUser } from "../db/users";
+import type {Req,Res} from '../http/types'
+
+const SESSION_TTL_SECONDS=3600
@@ -20,14 +23,28 @@ export async function currentUser(req: Req) {
-  const raw = req.cookies.session;
-  if (!raw) return null;
-  const payload = JSON.parse(atob(raw.split(".")[1]));
-  return loadUser(payload.sub);
+  const raw=req.cookies.session
+  if(!raw) return null
+  const verified = await verifyToken(raw)   // returns null on bad signature or expiry
+  if (!verified) return null
+  if (verified.iat + SESSION_TTL_SECONDS < Date.now()/1000) return null
+  const u = await loadUser(verified.sub)
+  return u
 }
